Here is the Python function `eval_expression(expr)` that evaluates mathematical expressions, following the standard order of operations (PEMDAS/BODMAS), handling parentheses, supporting negative numbers, and properly raising a `ZeroDivisionError` when division by zero occurs.

To ensure safety and full control over the parsing and error handling, this is implemented using a **Recursive Descent Parser** rather than Python's built-in `eval()` function.

```python
def eval_expression(expr: str) -> float:
    # Remove all whitespace from the expression
    expr = expr.replace(" ", "")
    if not expr:
        raise ValueError("Empty expression")

    class Parser:

        def __init__(self, s: str):
            self.s = s
            self.pos = 0

        def peek(self):
            if self.pos < len(self.s):
                return self.s[self.pos]
            return None

        def consume(self):
            char = self.peek()
            self.pos += 1
            return char

        def parse(self):
            value = self.parse_expression()
            if self.pos < len(self.s):
                raise ValueError(
                    f"Unexpected character at position {self.pos}: {self.peek()}"
                )
            return value

        # Expression -> Term { ('+' | '-') Term }
        def parse_expression(self):
            node = self.parse_term()
            while self.peek() in ("+", "-"):
                op = self.consume()
                right = self.parse_term()
                if op == "+":
                    node += right
                else:
                    node -= right
            return node

        # Term -> Factor { ('*' | '/') Factor }
        def parse_term(self):
            node = self.parse_factor()
            while self.peek() in ("*", "/"):
                op = self.consume()
                right = self.parse_factor()
                if op == "*":
                    node *= right
                else:
                    if right == 0:
                        raise ZeroDivisionError("division by zero")
                    node /= right
            return node

        # Factor -> [ '+' | '-' ] ( Number | '(' Expression ')' )
        def parse_factor(self):
            sign = 1
            if self.peek() in ("+", "-"):
                if self.consume() == "-":
                    sign = -1

            if self.peek() == "(":
                self.consume()  # consume '('
                node = self.parse_expression()
                if self.peek() == ")":
                    self.consume()  # consume ')'
                else:
                    raise ValueError("Mismatched parentheses")
                return sign * node
            elif self.peek() and (
                self.peek().isdigit() or self.peek() == "."
            ):
                return sign * self.parse_number()
            else:
                raise ValueError(f"Unexpected character: {self.peek()}")

        def parse_number(self):
            start = self.pos
            has_decimal = False
            while self.peek() and (
                self.peek().isdigit() or (self.peek() == "." and not has_decimal)
            ):
                if self.peek() == ".":
                    has_decimal = True
                self.consume()

            num_str = self.s[start : self.pos]
            if "." in num_str:
                return float(num_str)
            else:
                return int(num_str)

    parser = Parser(expr)
    result = parser.parse()

    # If the result is a whole float (e.g., 7.0), convert it to int for cleaner output
    if isinstance(result, float) and result.is_integer():
        return int(result)
    return result
```

### Examples of Usage:

```python
print(eval_expression("3 + 4 * (2 - 1)"))  # Output: 7
print(eval_expression("-5 + (3 * -2)"))  # Output: -11
print(eval_expression("10 / (5 - 5)"))  # Raises ZeroDivisionError
print(eval_expression("2.5 * (3 + 1)"))  # Output: 10
```

